INSERT IGNORE INTO roles(codigo,nombre) VALUES ('ADMIN','Administrador'),('COMPRAS','Compras'),('BODEGA','Bodega'),('FINANZAS','Finanzas'),('LECTOR','Solo lectura');
INSERT IGNORE INTO areas(nombre) VALUES ('Obras'),('Mantenimiento'),('Bodega Central');
INSERT IGNORE INTO categorias(nombre) VALUES ('Materiales de construcción'),('Seguridad y protección'),('Instalaciones hidráulicas');
INSERT IGNORE INTO proveedores(codigo,nombre,condiciones_pago) VALUES ('A','Proveedor A','30 días'),('B','Proveedor B','Contado'),('C','Proveedor C','15 días'),('D','Proveedor D','30 días'),('E','Proveedor E','Contado'),('F','Proveedor F','Contado');
INSERT IGNORE INTO materiales(sku,nombre,descripcion,especificacion,unidad,categoria_id) VALUES
('CEM-GRIS-50','Cemento gris 50 kg','Cemento de uso general','Saco de 50 kg','saco',(SELECT id FROM categorias WHERE nombre='Materiales de construcción')),
('VAR-03-G40','Varilla #3 grado 40','Acero de refuerzo','3/8 pulg · grado 40 · 6 m','unidad',(SELECT id FROM categorias WHERE nombre='Materiales de construcción')),
('BLK-12-20-40','Block 12 × 20 × 40','Bloque de concreto','12 × 20 × 40 cm','unidad',(SELECT id FROM categorias WHERE nombre='Materiales de construcción')),
('ARENA-M3','Arena','Arena para construcción','Metro cúbico','m³',(SELECT id FROM categorias WHERE nombre='Materiales de construcción')),
('GUA-NIT-L','Guantes de nitrilo talla L','Guante desechable','Talla L · nitrilo','par',(SELECT id FROM categorias WHERE nombre='Seguridad y protección')),
('GUA-TRAB-L','Guantes de trabajo L','Guante de protección reutilizable','Talla L · trabajo pesado','par',(SELECT id FROM categorias WHERE nombre='Seguridad y protección')),
('PVC-12-SDR135','Tubo PVC 1/2 SDR 13.5','Tubería hidráulica','1/2 pulg · SDR 13.5','unidad',(SELECT id FROM categorias WHERE nombre='Instalaciones hidráulicas'));
INSERT IGNORE INTO material_alias(material_id,alias,origen) SELECT id,'Saco cemento uso general','Mantenimiento' FROM materiales WHERE sku='CEM-GRIS-50';
INSERT IGNORE INTO material_alias(material_id,alias,origen) SELECT id,'CEM-GRIS-50','Bodega Central' FROM materiales WHERE sku='CEM-GRIS-50';
INSERT IGNORE INTO material_alias(material_id,alias,origen) SELECT id,'Hierro 3/8 x 6 m','Mantenimiento' FROM materiales WHERE sku='VAR-03-G40';
INSERT IGNORE INTO material_alias(material_id,alias,origen) SELECT id,'Guantes trabajo L','Obras' FROM materiales WHERE sku='GUA-TRAB-L';
INSERT IGNORE INTO ubicaciones(codigo,nombre,tipo,area_id) VALUES ('BOD-CENTRAL','Bodega Central','BODEGA',(SELECT id FROM areas WHERE nombre='Bodega Central')),('OBRA-01','Obra principal','OBRA',(SELECT id FROM areas WHERE nombre='Obras')),('MANT-01','Mantenimiento','OBRA',(SELECT id FROM areas WHERE nombre='Mantenimiento'));
INSERT IGNORE INTO proveedor_material(material_id,proveedor_id,sku_externo,plazo_dias) SELECT m.id,p.id,m.sku,CASE p.codigo WHEN 'A' THEN 3 WHEN 'B' THEN 4 WHEN 'C' THEN 5 ELSE 6 END FROM materiales m CROSS JOIN proveedores p WHERE (m.sku='CEM-GRIS-50' AND p.codigo IN('A','B')) OR (m.sku='VAR-03-G40' AND p.codigo IN('A','C','D')) OR (m.sku='BLK-12-20-40' AND p.codigo IN('B','C')) OR (m.sku='ARENA-M3' AND p.codigo IN('A','D')) OR (m.sku IN('GUA-NIT-L','GUA-TRAB-L') AND p.codigo IN('E','F')) OR (m.sku='PVC-12-SDR135' AND p.codigo IN('B','D'));
INSERT IGNORE INTO politicas_stock(material_id,ubicacion_id,stock_min,stock_max,demanda_prom,demanda_max,lead_time_dias) SELECT m.id,u.id,0,NULL,v.prom,v.maxi,v.lead_days FROM (SELECT 'CEM-GRIS-50' sku,40 prom,55 maxi,3 lead_days UNION ALL SELECT 'VAR-03-G40',120,160,5 UNION ALL SELECT 'BLK-12-20-40',600,900,4 UNION ALL SELECT 'ARENA-M3',6,10,2) v JOIN materiales m ON m.sku=v.sku JOIN ubicaciones u ON u.codigo='BOD-CENTRAL';
INSERT IGNORE INTO movimientos_stock(material_id,cantidad,tipo,ubicacion_destino_id,documento,motivo,idempotency_key) SELECT m.id,v.stock,'APERTURA',u.id,'INVENTARIO-INICIAL-2026','Saldo de apertura de datos académicos',CONCAT('seed-opening-',m.sku) FROM (SELECT 'CEM-GRIS-50' sku,190 stock UNION ALL SELECT 'VAR-03-G40',850 UNION ALL SELECT 'BLK-12-20-40',2800 UNION ALL SELECT 'ARENA-M3',14) v JOIN materiales m ON m.sku=v.sku JOIN ubicaciones u ON u.codigo='BOD-CENTRAL' WHERE NOT EXISTS(SELECT 1 FROM movimientos_stock x WHERE x.idempotency_key=CONCAT('seed-opening-',m.sku));
INSERT IGNORE INTO contratos(numero,proveedor_id,fecha_inicio,fecha_fin,condiciones) SELECT 'CTR-2026-A',id,'2026-01-01','2026-12-31','Precios de referencia del caso académico' FROM proveedores WHERE codigo='A';
INSERT IGNORE INTO contrato_detalle(contrato_id,material_id,precio_crc) SELECT c.id,m.id,v.precio FROM contratos c JOIN (SELECT 'CEM-GRIS-50' sku,6300 precio UNION ALL SELECT 'VAR-03-G40',2050) v JOIN materiales m ON m.sku=v.sku WHERE c.numero='CTR-2026-A';
INSERT IGNORE INTO precios_proveedor(material_id,proveedor_id,precio_crc,vigente_desde,fuente) SELECT m.id,p.id,v.precio,'2026-10-01','Datos del quiz académico' FROM (SELECT 'CEM-GRIS-50' sku,'A' prov,6300 precio UNION ALL SELECT 'CEM-GRIS-50','B',7100 UNION ALL SELECT 'VAR-03-G40','A',2050 UNION ALL SELECT 'VAR-03-G40','C',2150 UNION ALL SELECT 'VAR-03-G40','D',2600) v JOIN materiales m ON m.sku=v.sku JOIN proveedores p ON p.codigo=v.prov WHERE NOT EXISTS(SELECT 1 FROM precios_proveedor x WHERE x.material_id=m.id AND x.proveedor_id=p.id AND x.vigente_desde='2026-10-01');
INSERT IGNORE INTO ordenes_compra(numero,proveedor_id,area_id,fecha,estado,notas) SELECT v.numero,p.id,a.id,v.fecha,'RECIBIDA','Registro histórico de compras ficticias del quiz' FROM (SELECT 'OC-1041' numero,'A' prov,'Obras' area,'2026-10-02' fecha UNION ALL SELECT 'OC-1042','A','Obras','2026-10-02' UNION ALL SELECT 'OC-1047','B','Mantenimiento','2026-10-06' UNION ALL SELECT 'OC-1050','C','Obras','2026-10-08' UNION ALL SELECT 'OC-1053','C','Obras','2026-10-09' UNION ALL SELECT 'OC-1058','D','Mantenimiento','2026-10-13' UNION ALL SELECT 'OC-1061','A','Bodega Central','2026-10-15') v JOIN proveedores p ON p.codigo=v.prov JOIN areas a ON a.nombre=v.area;
INSERT IGNORE INTO orden_compra_detalle(orden_id,material_id,cantidad,precio_unitario_historico) SELECT o.id,m.id,v.cantidad,v.precio FROM (SELECT 'OC-1041' oc,'CEM-GRIS-50' sku,200 cantidad,6450 precio UNION ALL SELECT 'OC-1042','CEM-GRIS-50',200,6450 UNION ALL SELECT 'OC-1047','CEM-GRIS-50',40,7100 UNION ALL SELECT 'OC-1050','VAR-03-G40',500,2150 UNION ALL SELECT 'OC-1053','VAR-03-G40',480,2150 UNION ALL SELECT 'OC-1058','VAR-03-G40',60,2600 UNION ALL SELECT 'OC-1061','CEM-GRIS-50',300,6300) v JOIN ordenes_compra o ON o.numero=v.oc JOIN materiales m ON m.sku=v.sku;
INSERT IGNORE INTO reglas_negocio(clave,valor_json) VALUES ('duplicate_window_days','3'),('duplicate_quantity_tolerance','0.05'),('approval_thresholds','[{"max":250000,"role":"JEFATURA_AREA","quotes":1},{"max":2000000,"role":"COMPRAS","quotes":2},{"max":10000000,"role":"FINANZAS","quotes":3},{"max":null,"role":"GERENCIA_COMITE","quotes":3}]');
